class Translator:
    def __init__(self, language="en"):
        self.language = language if language in LANGUAGES else "en"
        self.index = list(LANGUAGES).index(self.language)

    def __call__(self, key, **values):
        row = MESSAGES.get(key)
        return (row[self.index] if row else key).format(**values)

    def agrees(self, answer):
        return answer.strip().casefold() in {"yes", "y", self("yes").casefold(), "si" if self.language in {"it", "es"} else self("yes").casefold()}
